Map<String,Runnable> rejestr = Map.of("A", () -> System.out.println("A"), "B", () -> System.out.println("B"));
void runTask(Map<String,Runnable> reg, String name) throws InterruptedException {
    Runnable r = reg.get(name);
    if (r == null) { System.out.println("Brak zadania: " + name); return; }
    Thread t = new Thread(r); t.start(); t.join();
}

