            Thread t = new Thread(self[0]);
            t.start();
            try { t.join(); } catch (InterruptedException e) {}
        }
    }
};
new Thread(self[0]).start();

long[] bufor = {0};
Thread[] watki = new Thread[5];
for (int i = 0; i < 5; i++) {
    final int wartosc = i + 1;
    watki[i] = new Thread(() -> { synchronized(bufor) { bufor[0] += wartosc; } });
    watki[i].start();
}
for (Thread t : watki) t.join();
System.out.println(bufor[0]); // 1+2+3+4+5 = 15

